package zsescrow

import (
	"strings"

	"github.com/TxnLab/zerosignal/go/solana"
)

// The cluster presets: where the program is deployed and how to reach it.
// They live here rather than in the payer SDK so a node reads the same table
// without importing the SDK, as Algorand's presets live in algod. The TS SDK
// keeps its own copy in sdk/src/network.ts; sdk_vocabulary_vectors.json pins
// the two together, generated by go/zs/vocabulary_vectors_test.go, so a
// change here fails that test rather than this package's.
const (
	ClusterDevnet   = "devnet"
	ClusterLocalnet = "localnet"
)

// Cluster is a preset's RPC endpoint and program id.
type Cluster struct {
	RPCEndpoint string
	Program     solana.PublicKey
}

// clusters have one program id: devnet's deployment, which a localnet started
// by contracts-solana's `make localnet` loads at the same address.
var clusters = map[string]Cluster{
	ClusterDevnet:   {RPCEndpoint: "https://api.devnet.solana.com", Program: ProgramID},
	ClusterLocalnet: {RPCEndpoint: "http://127.0.0.1:8899", Program: ProgramID},
}

// Clusters are the preset names.
func Clusters() []string { return []string{ClusterDevnet, ClusterLocalnet} }

// ClusterPreset is the preset named name, in any case, and false for a name
// that is none. Matching here rather than at each caller keeps a node's
// config and the payer SDK accepting the same spellings.
func ClusterPreset(name string) (Cluster, bool) {
	c, ok := clusters[strings.ToLower(name)]
	return c, ok
}
